import pickle
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
mols=pickle.load(open('molecules.pkl','rb'));X=np.load('coords.npy'); cols={'C':'#333333','H':'#cccccc','O':'red','N':'blue','Cl':'#25aa25','Si':'#cc9922'}
fig=plt.figure(figsize=(15,7))
for pane,view in enumerate([(25,-80),(10,0)]):
 ax=fig.add_subplot(1,2,pane+1,projection='3d');off=0
 for m in mols:
  for b in m.GetBonds():
   a=off+b.GetBeginAtomIdx();c=off+b.GetEndAtomIdx();
   if m.GetAtomWithIdx(b.GetBeginAtomIdx()).GetSymbol()=='H' or m.GetAtomWithIdx(b.GetEndAtomIdx()).GetSymbol()=='H':lw=.6;alpha=.35
   else:lw=2;alpha=1
   p=X[[a,c]];ax.plot(*p.T,color='gray',lw=lw,alpha=alpha)
  for i,a in enumerate(m.GetAtoms()):
   p=X[off+i];el=a.GetSymbol()
   ax.scatter(*p,c=cols[el],s=12 if el=='H' else 45,alpha=.5 if el=='H' else 1)
   if el!='H':ax.text(*p,f'{el}{off+i}',fontsize=7)
  off+=m.GetNumAtoms()
 ax.scatter(0,0,0,c='purple',s=120)
 for i in [0,1,3,10,15,34,35,53]:
  p=np.array([np.zeros(3),X[i]]);ax.plot(*p.T,c='purple',ls='--')
 ax.set_box_aspect([1,1,1]);center=(X.max(0)+X.min(0))/2;span=np.max(X.max(0)-X.min(0))/2+.2
 ax.set_xlim(center[0]-span,center[0]+span);ax.set_ylim(center[1]-span,center[1]+span);ax.set_zlim(center[2]-span,center[2]+span)
 ax.view_init(*view)
plt.tight_layout();plt.savefig('geometry.png',dpi=150)
# distances, angles, quality
print('Metal distances',[(i,round(np.linalg.norm(X[i]),3)) for i in [0,1,3,10,15,34,35,53]])
for i in [34,35,53]:
 for j in [34,35,53]:
  if i<j:print('angle',i,j,np.degrees(np.arccos(np.dot(X[i],X[j])/np.linalg.norm(X[i])/np.linalg.norm(X[j]))))
